// The gene database for the ACTIVE species. Gene tables are generated by
// scripts/species/buildSpeciesDatabase.mjs -- do not hand-edit them. The curated ball
// python source lives at scripts/species/sources/ballPythonCurated.json; edit that and
// rebuild. These generated tables are the app's ONLY gene data, so nothing can drift.
//
// Ball python is imported statically rather than through the registry because it is the
// default species: the app has to boot with a working gene database before anything has
// had a chance to await a species load. Every other species arrives via setActiveSpecies.
import ballPythonJson from '../config/species/ball-python.json';
import {
  DEFAULT_SPECIES_ID,
  getSpeciesById,
  loadSpeciesGeneTable,
  resolveSpeciesId,
} from './speciesRegistry';

// 'locality', 'physical' and 'other' come from Morphpedia's own classification. They were
// previously collapsed into 'polygenic', which mislabelled Normal, Hybrid, Paradox and a
// locality (Volta) as quantitative traits -- punnett.ts skips polygenic as non-Mendelian,
// so anything wrongly filed there was silently dropped from cross predictions.
export type GeneType =
  | 'recessive'
  | 'incomplete_dominant'
  | 'dominant'
  | 'polygenic'
  | 'locality'
  | 'physical'
  | 'other';

export type HealthFlag = 'wobble' | 'lethal_super' | 'infertility' | 'kinking';

export type GeneRecord = {
  geneName: string;
  geneType: GeneType;
  complex: string | null;
  hasSuperForm: boolean;
  superGeneName: string | null;
  aliases: string[];
  shorthand: string[];
  healthFlags: HealthFlag[];
  /**
   * Trade names that are the SAME allele as this gene, which a keeper may legitimately
   * choose as their label -- Trick / Hurricane / Blitz. Distinct from `aliases`: an alias
   * is a spelling that collapses onto the canonical name, whereas an equivalent name is
   * kept as typed. Genetics must still treat them as ONE gene; only the label differs.
   */
  equivalentNames?: string[];
  /** Free text as Morphpedia prints it -- "1992", "1990s", "~1995". Null when unlisted. */
  yearDiscovered?: string | null;
  /** rarest | lower | average | higher | common. Null when unlisted. */
  rarity?: string | null;
  notes?: string;
};

export type GeneAliasRow = {
  geneName: string;
  aliases: string[];
  shorthand: string[];
};

export type GeneGroups = {
  recessiveGenes: string[];
  incompleteDominantGenes: string[];
  dominantGenes: string[];
  polygenicGenes?: string[];
  localityGenes?: string[];
  physicalGenes?: string[];
  otherGenes?: string[];
  belComplexGenes: string[];
  blkELComplexGenes?: string[];
  spiderComplexGenes?: string[];
  eightBallComplexGenes?: string[];
  mahoganyComplexGenes?: string[];
  superStripeComplexGenes?: string[];
  axanthicLines?: string[];
  acidComplexGenes?: string[];
  clownComplexGenes?: string[];
  wobbleGenes?: string[];
  lethalSuperGenes?: string[];
  yellowBellyComplexGenes?: string[];
  patternModifierGenes?: string[];
  colorEnhancerGenes?: string[];
  darkeningGenes?: string[];
  stripeLinePatternGenes?: string[];
};

export type SpeciesGeneticsDatabase = {
  version: number;
  generatedAt: string;
  genes: GeneRecord[];
  groups: GeneGroups;
};

type RawGeneRecord = Omit<GeneRecord, 'aliases' | 'shorthand' | 'healthFlags'> & {
  aliases?: string[];
  shorthand?: string[];
  healthFlags?: string[];
};

type RawDatabase = Omit<SpeciesGeneticsDatabase, 'genes'> & {
  genes: RawGeneRecord[];
};

